message.content:
{
  "technical_and_design_decisions": [
    "Implement Capabilities Framework as three separate config maps (channel, application, orderer) containing string keys; binaries that do not support a required capability crash.",
    "Define capability consumer interfaces in fabric/common/channelconfig/api.go to decouple calling code from capability implementation details.",
    "For v1.1, introduce a single 'V1.1' capability per map that encapsulates all non-backwards compatible changes.",
    "Enforce orderer group capability activation before application group in orderer logic to prevent chain fork.",
    "Implement Read-Your-Writes (RYW) by extending chaincode shim with GetTrxState (or similar) that reads from the current transaction's write set before falling back to state DB.",
    "Refactor MSPConfig from a concrete struct to an interface to allow programmatic construction outside configtxgen.",
    "Remove chaincode singletons by introducing explicit dependency injection / context passing throughout chaincode lifecycle.",
    "Generate peer core.yaml and orderer.yaml in tests from a central World configuration using templating.",
    "Implement new lifecycle validation interface that returns endorsement/validation parameters; default for '+lifecycle' is auto-generated signature policy requiring majority of orgs.",
    "Capabilities are version-tied (V1.1) with expectation of superset V1.2 later."
  ],
  "assumptions": [
    "The starting codebase is Hyperledger Fabric v1.0 with existing configtxgen, chaincode shim, and test framework.",
    "Adding organizations to a running network is already technically possible via config update; the video task is documentation only.",
    "A single developer performs all activities sequentially; effort estimates are for one person.",
    "Documentation/video tasks include creating a simple PowerPoint diagram and a screen-capture video with basic editing.",
    "Performance evaluation for CouchDB uses existing Fabric benchmark samples and does not require building new tooling.",
    "All effort is expressed in workdays (8-hour days) for a developer familiar with Go and Hyperledger Fabric.",
    "The companion lifecycle task (FAB-13523) base code exists; we only implement the validation interface as specified."
  ],
  "activities": [
    {
      "activity_id": "ACT-01",
      "activity_name": "Capabilities config schema and parsing",
      "activity_description": "Define protobuf/config changes for capabilities maps at channel, application, and orderer levels; implement parsing and validation in channel config processing.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "ACT-02",
      "activity_name": "Capability interface and consumer switches",
      "activity_description": "Modify channelconfig/api.go to add capability interfaces (e.g., SetChannelModPolicyDuringCreate) and implement V1.1 capability checks in common/capabilities.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-03",
      "activity_name": "Orderer enforcement and crash handling",
      "activity_description": "Implement orderer logic to require orderer group capability before application group, and ensure peers/orderers crash on unsupported capabilities.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-04",
      "activity_name": "Capabilities framework tests",
      "activity_description": "Write unit and integration tests covering config updates, enforcement, and crash behavior for capabilities.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "ACT-05",
      "activity_name": "RYW shim API and simulation implementation",
      "activity_description": "Extend chaincode stub with GetTrxState (or similar) to read transaction-local writes; modify transaction simulation context to support read-your-writes.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "ACT-06",
      "activity_name": "RYW tests",
      "activity_description": "Add unit and chaincode-level tests verifying read-your-writes semantics during transaction execution.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-07",
      "activity_name": "Create org addition diagram",
      "activity_description": "Produce a PowerPoint (or similar) diagram illustrating the process of adding an org to a running network.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "ACT-08",
      "activity_name": "Record and edit org addition video",
      "activity_description": "Script, screen-record, and edit a video demonstrating dynamic org addition without network downtime.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-09",
      "activity_name": "Write org addition process document",
      "activity_description": "Author step-by-step textual documentation detailing the org addition process shown in the video.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "ACT-10",
      "activity_name": "Setup CouchDB performance benchmark",
      "activity_description": "Configure Fabric network with CouchDB state database and prepare query benchmark scripts using existing samples.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-11",
      "activity_name": "Run benchmarks and collect metrics",
      "activity_description": "Execute benchmark queries against CouchDB, measure latency/throughput, and collect results.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-12",
      "activity_name": "Produce CouchDB performance report",
      "activity_description": "Analyze collected metrics and document performance characteristics of Fabric queries with CouchDB.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "ACT-13",
      "activity_name": "Refactor MSPConfig to interface",
      "activity_description": "Change MSPConfig from concrete type to interface, update configtxgen and other internal usages to construct config blocks programmatically.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-14",
      "activity_name": "MSPConfig interface tests",
      "activity_description": "Add tests verifying external construction of channel config blocks using the new MSPConfig interface.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "ACT-15",
      "activity_name": "Remove chaincode singletons refactor",
      "activity_description": "Identify and eliminate global chaincode singletons, replacing with dependency injection or context-based passing.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "ACT-16",
      "activity_name": "Singleton removal tests",
      "activity_description": "Update and add unit/integration tests to ensure chaincode behavior remains correct after singleton removal.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-17",
      "activity_name": "Test config generation from World config",
      "activity_description": "Modify test framework so peer core.yaml and orderer.yaml are generated from World config values via templating.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-18",
      "activity_name": "Test config generation tests",
      "activity_description": "Verify generated YAML files are valid and correctly parameterized in test runs.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "ACT-19",
      "activity_name": "Lifecycle validation interface implementation",
      "activity_description": "Implement interface returning validation parameters for chaincode; include +lifecycle default majority signature policy and stub for channel config policy evaluation.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "ACT-20",
      "activity_name": "Lifecycle validation tests",
      "activity_description": "Test validation parameter retrieval for normal chaincodes and the +lifecycle special case.",
      "most_likely_effort": 2
    }
  ],
  "reported_total": {
    "most_likely_effort": 53
  }
}

